// run
package main

import (
	"fmt"
	"runtime"
)

type res struct{ id int }

var finalized []int

func make1(id int) {
	r := &res{id}
	runtime.SetFinalizer(r, func(x *res) { finalized = append(finalized, x.id) })
}

func main() {
	for i := 0; i < 5; i++ {
		make1(i)
	}
	for i := 0; i < 4; i++ {
		runtime.GC()
	}
	fmt.Println("finalized count:", len(finalized))
	kept := &res{99}
	runtime.SetFinalizer(kept, func(x *res) { fmt.Println("should not run", x.id) })
	runtime.GC()
	runtime.GC()
	if kept == nil {
		fmt.Println("unreachable")
	}
	fmt.Println("kept alive:", kept.id)
	cleared := &res{7}
	runtime.SetFinalizer(cleared, func(x *res) { fmt.Println("cleared finalizer ran") })
	runtime.SetFinalizer(cleared, nil)
	fmt.Println("done")
}

