// run
package main

import (
	"fmt"
	"runtime"
)

type obj struct{ n int }

func main() {
	var throughIface interface{}
	var throughMap map[string]*obj
	var throughSlice []*obj
	var throughClosure func() int

	o1 := &obj{1}
	throughIface = o1
	throughMap = map[string]*obj{"k": {2}}
	throughSlice = []*obj{{3}}
	o4 := &obj{4}
	throughClosure = func() int { return o4.n }

	alive := 0
	for _, o := range []*obj{o1, throughMap["k"], throughSlice[0], o4} {
		runtime.SetFinalizer(o, func(x *obj) { alive-- })
		alive++
	}
	for i := 0; i < 3; i++ {
		runtime.GC()
	}
	fmt.Println("still reachable:", alive == 4)
	fmt.Println(throughIface.(*obj).n, throughMap["k"].n, throughSlice[0].n, throughClosure())
	if throughIface == nil || throughMap == nil || throughSlice == nil || throughClosure == nil {
		fmt.Println("unreachable")
	}
}

