// run
package main

import (
	"fmt"
	"runtime"
)

type block struct {
	data [64]byte
	next *block
}

func main() {
	var keep *block
	for i := 0; i < 200000; i++ {
		b := &block{}
		b.data[0] = byte(i)
		if i%50000 == 0 {
			b.next = keep
			keep = b
		}
	}
	var m runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&m)
	fmt.Println("collected:", m.NumGC > 0, m.Frees > 0, m.Frees < m.Mallocs)
	fmt.Println("bounded:", m.HeapAlloc*20 < m.TotalAlloc)
	n := 0
	for p := keep; p != nil; p = p.next {
		n++
	}
	fmt.Println("live chain:", n)
	if keep == nil {
		fmt.Println("unreachable")
	}
}

