	if want, got = a^c32a, xor32(a); got != want {
		panic(fmt.Sprintf("xor32(%x) = %x, want %x", a, got, want))
	}
	if want, got = c32a-a, subr32a(a); got != want {
		panic(fmt.Sprintf("subr32a(%x) = %x, want %x", a, got, want))
